import{_ as i,o as e,c as s,ag as t}from"./chunks/framework.DWOJQht4.js";const u=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md","lastUpdated":1792724420000}'),l={name:"guide/quick-start.md"};function d(h,a,n,o,p,c){return e(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>这页只保留 <strong>最短可运行路径</strong>：下载、执行、访问。<br> 如果你要看 <code>systemd</code>、配置文件、数据库切换等生产部署细节，请跳转到 <a href="/CloudCTF/guide/production-deploy.html">生产部署</a>。</p><p>如果你想先体验已部署好的环境，可以访问在线预览：</p><ul><li><a href="http://cloud-ctf.lostpeach.cn/" target="_blank" rel="noreferrer">http://cloud-ctf.lostpeach.cn/</a></li></ul><h2 id="前置要求" tabindex="-1">前置要求 <a class="header-anchor" href="#前置要求" aria-label="Permalink to &quot;前置要求&quot;">​</a></h2><ul><li>Linux x86_64 或 ARM64</li><li>可执行文件下载权限</li></ul><blockquote><p>快速开始默认<strong>不要求任何额外配置</strong>。<br> 未显式配置时，服务会使用内置默认值启动，并默认使用 SQLite。</p></blockquote><h2 id="_1-下载二进制" tabindex="-1">1. 下载二进制 <a class="header-anchor" href="#_1-下载二进制" aria-label="Permalink to &quot;1. 下载二进制&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -LO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/hexbay/CloudCTF/releases/latest/download/cloudctf-linux-amd64</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -LO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/hexbay/CloudCTF/releases/latest/download/cloudctf-linux-amd64.sha256</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloudctf-linux-amd64.sha256</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloudctf-linux-amd64</span></span></code></pre></div><p>如果你是 ARM64 机器，请将文件名替换为：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloudctf-linux-arm64</span></span></code></pre></div><h2 id="_2-直接启动" tabindex="-1">2. 直接启动 <a class="header-anchor" href="#_2-直接启动" aria-label="Permalink to &quot;2. 直接启动&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./cloudctf-linux-amd64</span></span></code></pre></div><p>默认情况下：</p><ul><li>监听地址：<code>0.0.0.0:8005</code></li><li>数据库：<code>sqlite://data/cloudctf.db</code></li><li>选手端：<code>/</code></li><li>管理后台：<code>/admin</code></li></ul><h2 id="_3-访问平台" tabindex="-1">3. 访问平台 <a class="header-anchor" href="#_3-访问平台" aria-label="Permalink to &quot;3. 访问平台&quot;">​</a></h2><p>启动后访问：</p><ul><li>选手端：<code>http://&lt;server&gt;:8005/</code></li><li>管理后台：<code>http://&lt;server&gt;:8005/admin</code></li><li>健康检查：<code>http://&lt;server&gt;:8005/healthz</code></li></ul><h2 id="默认账号" tabindex="-1">默认账号 <a class="header-anchor" href="#默认账号" aria-label="Permalink to &quot;默认账号&quot;">​</a></h2><p>首次启动后，系统会自动创建账号。管理员密码不是固定密码，而是在首次运行时随机生成：</p><table tabindex="0"><thead><tr><th>角色</th><th>用户名</th><th>密码</th></tr></thead><tbody><tr><td>管理员</td><td><code>admin</code></td><td>查看 <code>data/.env</code> 中的 <code>FIRST_SUPERUSER_PASSWORD</code></td></tr><tr><td>选手</td><td><code>player1</code></td><td><code>password123</code></td></tr></tbody></table><p>查看管理员密码：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;^FIRST_SUPERUSER_PASSWORD=&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/.env</span></span></code></pre></div><p><code>data/.env</code> 由程序根据 <code>.env.example</code> 自动创建。请勿删除或公开该文件，正式环境首次登录后建议立即修改管理员密码。</p><h2 id="常见操作" tabindex="-1">常见操作 <a class="header-anchor" href="#常见操作" aria-label="Permalink to &quot;常见操作&quot;">​</a></h2><p>停止服务：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Ctrl+C</span></span></code></pre></div><p>重新启动：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./cloudctf-linux-amd64</span></span></code></pre></div><h2 id="遇到问题" tabindex="-1">遇到问题？ <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题？&quot;">​</a></h2><p>如果你只是想确认服务能不能跑起来，先检查：</p><ol><li>文件是否有执行权限</li><li><code>8005</code> 端口是否被占用</li><li>当前目录是否可写（SQLite 默认会在本地创建数据库文件）</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/CloudCTF/guide/production-deploy.html">生产部署</a></li><li><a href="/CloudCTF/guide/architecture.html">技术架构</a></li><li><a href="/CloudCTF/guide/admin-guide.html">管理员指南</a></li></ul>`,34)])])}const k=i(l,[["render",d]]);export{u as __pageData,k as default};
